import json
from pathlib import Path
D = Path('.bd-prune-part4')
idx = json.load(open(D/'batch-index.json'))
post3_bodies = json.load(open('/home/ubuntu/repos/angr-memories/round3/snapshot-post-prune.json'))
post3 = set(post3_bodies)
cur = json.load(open(D/'snapshot-pre-prune.json'))
cites = json.load(open(D/'cites-graph.json'))
done = {'R4-INVARIANT-1','R4-INVARIANT-2','R4-INVARIANT-3','R4-INVARIANT-4'}

delta, autokeep = [], []
for b, keys in sorted(idx.items()):
    if b in done: continue
    for k in keys:
        if k not in post3 or cur.get(k) != post3_bodies.get(k):
            delta.append(k)
        else:
            autokeep.append(k)
assert len(delta) == 229 and len(autokeep) == 553, (len(delta), len(autokeep))

# auto-keep manifest for scrubbed, unchanged round-3 survivors
with open(D/'manifest-R4-autokeep.jsonl','w') as f:
    for k in sorted(autokeep):
        f.write(json.dumps({"key": k, "verdict": "keep",
            "reason": "round-3 survivor, body unchanged since 2026-07-04 scrub; delta-scope auto-keep",
            "batch": "R4-AUTOKEEP"})+'\n')

# delta batches: sort so prefix families stay adjacent, split into 5
delta.sort()
n = 5
chunks = [delta[i*len(delta)//n:(i+1)*len(delta)//n] for i in range(n)]
inv = {}
for citer, cited in cites.items():
    for c in cited:
        inv.setdefault(c, []).append(citer)
for i, chunk in enumerate(chunks, 1):
    name = f'R4D-{i}'
    bodies = {k: cur[k] for k in chunk}
    (D/f'bodies-{name}.json').write_text(json.dumps(bodies, indent=1))
    out = {k: cites[k] for k in chunk if k in cites}
    inn = {k: inv[k] for k in chunk if k in inv}
    (D/f'cites-{name}.json').write_text(json.dumps({"out": out, "in": inn}, indent=1))
    idx[name] = chunk
for b in list(idx):
    if b not in done and not b.startswith('R4D-'):
        del idx[b]   # superseded by delta batches + autokeep
(D/'batch-index.json').write_text(json.dumps(idx, indent=1))
print('autokeep rows:', len(autokeep))
print('delta batches:', {f'R4D-{i+1}': len(c) for i, c in enumerate(chunks)})
EOF

